CREATE TABLE IF NOT EXISTS "ai_feedback" (
    "id"             bigint       NOT NULL GENERATED BY DEFAULT AS IDENTITY,
    "content"        varchar(2048) NOT NULL,
    "screenshot_urls" varchar(4096) DEFAULT NULL,
    "session_id"     varchar(64)   DEFAULT NULL,
    "status"         tinyint       NOT NULL DEFAULT 10,
    "submitter_id"   bigint        NOT NULL,
    "creator"        varchar(64)   DEFAULT '',
    "create_time"    datetime      NOT NULL DEFAULT CURRENT_TIMESTAMP,
    "updater"        varchar(64)   DEFAULT '',
    "update_time"    datetime      NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,
    "deleted"        bit           NOT NULL DEFAULT 0,
    "tenant_id"      bigint        NOT NULL DEFAULT 0,
    PRIMARY KEY ("id")
) COMMENT 'AI 平台问题反馈表';

CREATE TABLE IF NOT EXISTS "ai_channel" (
    "id"          bigint        NOT NULL GENERATED BY DEFAULT AS IDENTITY,
    "name"        varchar(64)   NOT NULL,
    "provider"    varchar(32)   NOT NULL,
    "base_url"    varchar(512)  NOT NULL,
    "api_key"     varchar(1024) DEFAULT NULL,
    "enabled"     bit           NOT NULL DEFAULT 1,
    "owner_type"  varchar(16)   NOT NULL,
    "creator"     varchar(64)   DEFAULT '',
    "create_time" datetime      NOT NULL DEFAULT CURRENT_TIMESTAMP,
    "updater"     varchar(64)   DEFAULT '',
    "update_time" datetime      NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,
    "deleted"     bit           NOT NULL DEFAULT 0,
    "tenant_id"   bigint        NOT NULL DEFAULT 0,
    PRIMARY KEY ("id")
) COMMENT 'AI 平台模型渠道表';

CREATE TABLE IF NOT EXISTS "ai_model" (
    "id"             bigint         NOT NULL GENERATED BY DEFAULT AS IDENTITY,
    "channel_id"     bigint         NOT NULL,
    "model_id"       varchar(128)   NOT NULL,
    "name"           varchar(64)    NOT NULL,
    "context_window" int            DEFAULT NULL,
    "input_price"    decimal(12, 6) DEFAULT NULL,
    "output_price"   decimal(12, 6) DEFAULT NULL,
    "capabilities"   varchar(1024)  DEFAULT NULL,
    "enabled"        bit            NOT NULL DEFAULT 1,
    "creator"        varchar(64)    DEFAULT '',
    "create_time"    datetime       NOT NULL DEFAULT CURRENT_TIMESTAMP,
    "updater"        varchar(64)    DEFAULT '',
    "update_time"    datetime       NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,
    "deleted"        bit            NOT NULL DEFAULT 0,
    "tenant_id"      bigint         NOT NULL DEFAULT 0,
    PRIMARY KEY ("id")
) COMMENT 'AI 平台模型元数据表';

CREATE TABLE IF NOT EXISTS "ai_agent_spec" (
    "id"                bigint       NOT NULL GENERATED BY DEFAULT AS IDENTITY,
    "name"              varchar(64)  NOT NULL,
    "spec_code"         varchar(64)  NOT NULL,
    "icon"              varchar(128) DEFAULT NULL,
    "owner_level"       varchar(16)  NOT NULL DEFAULT 'TENANT',
    "owner_user_id"     bigint       DEFAULT NULL,
    "latest_version_no" int          NOT NULL DEFAULT 0,
    "current_version_no" int         DEFAULT NULL,
    "draft"             text         DEFAULT NULL,
    "creator"           varchar(64)  DEFAULT '',
    "create_time"       datetime     NOT NULL DEFAULT CURRENT_TIMESTAMP,
    "updater"           varchar(64)  DEFAULT '',
    "update_time"       datetime     NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,
    "deleted"           bit          NOT NULL DEFAULT 0,
    "tenant_id"         bigint       NOT NULL DEFAULT 0,
    PRIMARY KEY ("id")
) COMMENT 'AI 平台智能体规格表（行为性配置含给 LLM 的自描述，全在 draft JSON 内随版本快照固化；spec_code 唯一性按归属层级由应用层+生产库部分唯一索引保证）';

CREATE TABLE IF NOT EXISTS "ai_agent_spec_version" (
    "id"          bigint       NOT NULL GENERATED BY DEFAULT AS IDENTITY,
    "spec_id"     bigint       NOT NULL,
    "version_no"  int          NOT NULL,
    "snapshot"    text         NOT NULL,
    "remark"      varchar(255) DEFAULT NULL,
    "creator"     varchar(64)  DEFAULT '',
    "create_time" datetime     NOT NULL DEFAULT CURRENT_TIMESTAMP,
    "updater"     varchar(64)  DEFAULT '',
    "update_time" datetime     NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,
    "deleted"     bit          NOT NULL DEFAULT 0,
    "tenant_id"   bigint       NOT NULL DEFAULT 0,
    PRIMARY KEY ("id")
) COMMENT 'AI 平台智能体规格版本表（不可变快照）';

CREATE TABLE IF NOT EXISTS "ai_skill" (
    "id"                 bigint       NOT NULL GENERATED BY DEFAULT AS IDENTITY,
    "name"               varchar(64)  NOT NULL,
    "description"        varchar(512) NOT NULL,
    "latest_version_no"  int          NOT NULL DEFAULT 0,
    "current_version_no" int          DEFAULT NULL,
    "draft_content_id"   bigint       DEFAULT NULL,
    "creator"            varchar(64)  DEFAULT '',
    "create_time"        datetime     NOT NULL DEFAULT CURRENT_TIMESTAMP,
    "updater"            varchar(64)  DEFAULT '',
    "update_time"        datetime     NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,
    "deleted"            bit          NOT NULL DEFAULT 0,
    "tenant_id"          bigint       NOT NULL DEFAULT 0,
    PRIMARY KEY ("id")
) COMMENT 'AI 平台技能表（主体与指针，零内容列，ADR-0003）';

CREATE TABLE IF NOT EXISTS "ai_skill_content" (
    "id"          bigint       NOT NULL GENERATED BY DEFAULT AS IDENTITY,
    "skill_id"    bigint       NOT NULL,
    "skill_md"    text         NOT NULL,
    "creator"     varchar(64)  DEFAULT '',
    "create_time" datetime     NOT NULL DEFAULT CURRENT_TIMESTAMP,
    "updater"     varchar(64)  DEFAULT '',
    "update_time" datetime     NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,
    "deleted"     bit          NOT NULL DEFAULT 0,
    "tenant_id"   bigint       NOT NULL DEFAULT 0,
    PRIMARY KEY ("id")
) COMMENT 'AI 平台技能内容表（一行一份 SKILL.md，不可变）';

-- 注：(content_id, path) 的业务唯一性由 PG 生产库的部分唯一索引
-- uk_ai_skill_resource（WHERE deleted = 0）保证；H2 不支持部分索引，测试库不建约束，
-- 唯一性行为由应用层（SkillContent 值对象按 Map 天然去重）兜底。
CREATE TABLE IF NOT EXISTS "ai_skill_resource" (
    "id"          bigint       NOT NULL GENERATED BY DEFAULT AS IDENTITY,
    "content_id"  bigint       NOT NULL,
    "path"        varchar(500) NOT NULL,
    "content"     text         NOT NULL,
    "creator"     varchar(64)  DEFAULT '',
    "create_time" datetime     NOT NULL DEFAULT CURRENT_TIMESTAMP,
    "updater"     varchar(64)  DEFAULT '',
    "update_time" datetime     NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,
    "deleted"     bit          NOT NULL DEFAULT 0,
    "tenant_id"   bigint       NOT NULL DEFAULT 0,
    PRIMARY KEY ("id")
) COMMENT 'AI 平台技能资源文件表（一行一个附属文件）';

CREATE TABLE IF NOT EXISTS "ai_skill_version" (
    "id"          bigint       NOT NULL GENERATED BY DEFAULT AS IDENTITY,
    "skill_id"    bigint       NOT NULL,
    "version_no"  int          NOT NULL,
    "content_id"  bigint       NOT NULL,
    "remark"      varchar(255) DEFAULT NULL,
    "creator"     varchar(64)  DEFAULT '',
    "create_time" datetime     NOT NULL DEFAULT CURRENT_TIMESTAMP,
    "updater"     varchar(64)  DEFAULT '',
    "update_time" datetime     NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,
    "deleted"     bit          NOT NULL DEFAULT 0,
    "tenant_id"   bigint       NOT NULL DEFAULT 0,
    PRIMARY KEY ("id")
) COMMENT 'AI 平台技能版本表（不可变指针行）';
